from stage import *

SOURCES=HISTORICAL/'sources'
P11=source('P11:1603.04993v3',SOURCES/'1603.04993v3.pdf',SOURCES/'1603.04993v3.txt','Section2.1 definition and explicit light-LQ extensions',[18,19,20,21,22],[20,21],'https://arxiv.org/pdf/1603.04993v3')
P18=source('P18:hep-ph/0702287v4',SOURCES/'hep-ph_0702287v4.pdf',SOURCES/'hep-ph_0702287v4.txt','SectionII Eqs1-8; SectionIII TableI',[1,2,3,4],[2,3],'https://arxiv.org/pdf/hep-ph/0702287v4')
AUX=source('AUX-P11-ref74:hep-ph/0504276v1',HERE/'sources/hep-ph_0504276v1.pdf',HERE/'sources/hep-ph_0504276v1.txt','AppendixA particle content and full potential EqsA1-A5; TableI',[4,5,19,20,21],[20],'https://arxiv.org/pdf/hep-ph/0504276v1')
claims=[
 {'id':'gg-fields','basis':'P11_source_statement','locator':'P11 Section2.1 PDF/printedpp18,20','fact':'All SM fields in unified multiplets are explicitly LH. Three10_i=(e^c,u^c,Q),threebar5_i=(L,d^c). GG scalar sector one5 and one24. Vector24 is the implied SU5 connection, not extra matter.'},
 {'id':'tensor-weights','basis':'mathematical_highest_weight_conversion','locator':'P11 Section2.1 contractions pp18,20,22; AUX AppendixA EqA4','fact':'A4 fundamental5 [1,0,0,0],bar5 [0,0,0,1],antisymmetric upper10 [0,1,0,0],symmetric upper15 [2,0,0,0],adjoint24 [1,0,0,1]. Weights are not inferred from bare dimensions: upper-index tensors and displayed SM decompositions fix orientation.'},
 {'id':'adjoint-real','basis':'registered_auxiliary_source_and_derived_field_reality','locator':'AUX AppendixA EqA5 PDF/printedp20; TableI p5; P18 TableI p3','fact':'GG Sigma is the Hermitian adjoint coordinate: complete real scalar potential uses TrSigma^2,TrSigma^3 and Psi-dagger Sigma Psi with no independent Sigma-dagger or added h.c.; complex Psi/Phi are explicitly conjugated. This fixes the ordinary real24, not an unconstrained complex24. Independent check: neutral Sigma8 gives b3=1/2 and Sigma3 b2=1/3 in threshold tables, the single-real-scalar coefficients T(R)/6, not complexT(R)/3. Therefore one irreducible-real24 module. This resolves earlier unestablished counting by source potential and degrees of freedom, not by assuming every real-type irrep is a real field.'},
 {'id':'gg-extra','basis':'P11_source_statement','locator':'P11 Section2.1 PDF/printedp20 and Figure3 p21','fact':'Add one5 plus two scalar10 to GG at unified scale: TOTAL two5,one24,two10. In stated light regime only two complex Higgs doublets and two complex scalar(3,2,1/6) survive besides SM fermions/gauge fields. Do not union light and unified inventories.'},
 {'id':'gg-15','basis':'P11_source_statement_and_registered_primary_model_support','locator':'P11 Section2.1 PDF/printedp22; AUX AppendixA EqsA1-A4 p19','fact':'Alternative adds one scalar15 to GG. Its (1,3,1)+(6,1,-2/3)+(3,2,1/6) and symmetric upper tensor identify [2,0,0,0]. Both5 and15 are complex type; each one source complex field is one underlying real module, not doubled.'},
 {'id':'adjoint-model','basis':'P18_source_statement_and_chiral_coordinate_derivation','locator':'P18 SectionII PDFp2 Eqs1,4, SectionIII p3 Eq8/TableI','fact':'NonSUSY model has threebar5+10 ordinary LH families, one extra adjoint fermion24, scalar5H,real24H and complex45H. Vnu=bar5_i 24 5H plus massTr24^2 identifies one independent adjoint Weyl, not a Dirac pair. Source45 has antisymmetric upper indices alpha,beta and lowerdelta, trace removed; A4[0,1,0,1]. Canonical scalar representative may be its full dual[1,0,1,0], with one real-module copy, without conjugating the fermions.'}
]

def base():return [field('10_i',[0,1,0,0],copies=3),field('bar5_i',[0,0,0,1],copies=3),field('24_H',[1,0,0,1],'S',reality='real'),field('5_H',[1,0,0,0],'S')]
base_map=[mapping('10_i',[120],['gg-fields','tensor-weights'],model='su5-georgi-glashow-review',regime=35),mapping('bar5_i',[121],['gg-fields','tensor-weights'],model='su5-georgi-glashow-review',regime=35),mapping('24_H',[122],['gg-fields','adjoint-real','tensor-weights'],model='su5-georgi-glashow-review',regime=35),mapping('5_H',[123],['gg-fields','tensor-weights'],model='su5-georgi-glashow-review',regime=35)]

def main():
    frozen_unchanged()
    shared={'sources':[P11,AUX],'claims':claims[:5],'omitted_source_fields':[{'source_field_id':124,'reason':'Gauge connection implied by A4, not independent matter.'}],'auxiliary_registration':'Auxiliary is P11 reference74, inspected only to establish its GG baseline scalar counting. It is not an additional seed paper/model. A5 inference and TableI consistency are labelled derivations.'}
    stage('su5-georgi-glashow-review','P11','1603.04993v3',spec('P11','Georgi-Glashow unified gauge/matter inventory',base()),deepcopy(shared),deepcopy(base_map),regime={'source_regime_id':35,'description':'Unified4D gauge-basis spectrum before breaking; no separately appended GSM.'})
    extra=base()+[field('additional5_H',[1,0,0,0],'S'),field('10_H,a',[0,1,0,0],'S',copies=2)]
    inherited=deepcopy(base_map)
    for m in inherited:m['mapping_basis']='explicitly_inherited_GG_fields_from_same_P11_source'
    stage('su5-gg-extra5-two10','P11','1603.04993v3',spec('P11','GG plus one extra5 and two scalar10',extra),deepcopy(shared),inherited+[mapping('additional5_H',[125],['gg-extra','tensor-weights'],model='su5-gg-extra5-two10',regime=36),mapping('10_H,a',[126],['gg-extra','tensor-weights'],model='su5-gg-extra5-two10',regime=36)],limitations=['This candidate is unified regime36. Source light regime37 fields127/128 are not extra simultaneous unified matter; a separate complete low-energy candidate can be recorded.'],regime={'source_regime_id':36,'description':'Full unified spectrum, GG baseline inherited explicitly.'})
    stage('su5-gg-scalar15','P11','1603.04993v3',spec('P11','GG plus scalar15',base()+[field('15_H',[2,0,0,0],'S')]),deepcopy(shared),deepcopy(inherited)+[mapping('15_H',[129],['gg-15','tensor-weights'],model='su5-gg-scalar15',regime=38)],regime={'source_regime_id':38,'description':'Full unified GG+15, not the scalar15 sector alone.'})
    adjfields=[field('bar5_i',[0,0,0,1],copies=3),field('10_i',[0,1,0,0],copies=3),field('24_F',[1,0,0,1]),field('5H',[1,0,0,0],'S'),field('24H',[1,0,0,1],'S',reality='real'),field('45H',[0,1,0,1],'S')]
    adjmap=[mapping(f['label'],[i],['adjoint-model','tensor-weights']+(['adjoint-real'] if i==227 else []),model='su5-adjoint-renormalizable',regime=59) for f,i in zip(adjfields,range(223,229))]
    stage('su5-adjoint-renormalizable','P18','hep-ph/0702287v4',spec('P18','Renormalizable adjoint SU5',adjfields),{'sources':[P18,AUX],'claims':claims,'source_count_resolution':'P18 TableI itself resolves real24H using its exact neutral octet/triplet threshold contributions; no viability condition imposed.'},adjmap,regime={'source_regime_id':59,'description':'NonSUSY unified4D gauge basis. Optional typeI/typeII alternatives not added to this adjoint model.'})
    p22=source('P22:hep-ph/0406039v2',SOURCES/'hep-ph_0406039v2.pdf',SOURCES/'hep-ph_0406039v2.txt','Section2.6 Eqs2.66-2.68 and footnote13',[46,47],[46],'https://arxiv.org/pdf/hep-ph/0406039v2')
    partial=[]
    for label,w,identifier in [('bar5_i',[0,0,0,1],270),('10_i',[0,1,0,0],271)]:
        scalar=field(label+' scalar',w,'S',copies=3)
        normalized_scalar,_=real_scalar(deepcopy(scalar),[{'id':'unified','family':'A','rank':4}],'complex')
        partial += [{'source_field_id':identifier,'source_superfield':label,'source_copies':3,'components':[normalized_scalar,field(label+' Weyl',w,copies=3)],'claim_ids':['rpv-sector']}]
    reason='Section2.6 specifies SU5 matter superfields/operators and mentions5u/bar5d Higgs in footnote13, but does not choose a complete GUT-breaking/gauge/Higgs completion. Its matter sector can be filled precisely; a full SU5 inventory cannot be inferred by appending an arbitrary minimal SUSY GUT.'
    ev={'sources':[p22],'claims':[{'id':'rpv-sector','basis':'source_statement_and_component_expansion','locator':'P22 Section2.6 PDFpp46-47 Eq2.66 and footnote13','fact':'Threebar5_i containsL,Dc;three10_i containsQ,Uc,Ec. They are LH chiral superfields: each has one complex scalar plus one LH Weyl. Scalarsbar5/5 share an underlying real module, but fermionicbar5 staysbar5.'}],'resolved_sector_fields':partial,'scientific_source_omissions':[{'value_status':'not_specified_by_source_in_operator_sector','item':'chosen full GUT-breaking completion','locator':'Section2.6 pp46-47'}]}
    stage('su5-rpv-trilinear-sector','P22','hep-ph/0406039v2',None,ev,[mapping(x['source_superfield'],[x['source_field_id']],['rpv-sector'],model='su5-rpv-trilinear-sector',regime=81) for x in partial],status='source_sector_filled_full_inventory_not_specified',limitations=[reason],regime={'source_regime_id':81,'description':'SU5 superfield operator sector, not a complete model candidate.'})
    frozen_unchanged()

if __name__=='__main__':main()
